    private const int PageSize = 6;

    [SupplyParameterFromQuery] public string? SearchKeyword { get; set; }
    [SupplyParameterFromQuery] public int? CategoryId { get; set; }
    [SupplyParameterFromQuery] public string? StorageFilter { get; set; }
    [SupplyParameterFromQuery] public int? CurrentPage { get; set; }

    private List<Product> _products = new();
    private List<Category> _categories = new();
    private int _page = 1, _totalPages = 1;
    private string? _keyword, _filterStorage;
    private int _filterCategory;

    private bool _showModal;
    private Product _edit = new();
    private string? _formError, _alert, _alertType = "success";

    protected override async Task OnParametersSetAsync()
    {
        _keyword = SearchKeyword;
        _filterCategory = CategoryId ?? 0;
        _filterStorage = StorageFilter ?? "";
        await LoadAsync();
    }

    private async Task LoadAsync()
    {
        await using var db = await DbFactory.CreateDbContextAsync();
        _categories = await db.Categories.OrderBy(c => c.DisplayOrder).ToListAsync();

        var query = db.Products.Include(p => p.Category).AsQueryable();
        if (!string.IsNullOrWhiteSpace(SearchKeyword))
        {
            var kw = SearchKeyword.Trim().ToLower();
            query = query.Where(p => p.Name.ToLower().Contains(kw) || p.ModelSeries.ToLower().Contains(kw) || p.Color.ToLower().Contains(kw));
        }
        if (CategoryId is > 0) query = query.Where(p => p.CategoryId == CategoryId);
        if (!string.IsNullOrWhiteSpace(StorageFilter)) query = query.Where(p => p.Storage == StorageFilter);

        var total = await query.CountAsync();
        _totalPages = (int)Math.Ceiling(total / (double)PageSize);
        _page = Math.Max(1, CurrentPage ?? 1);
        if (_page > _totalPages && _totalPages > 0) _page = _totalPages;

        _products = await query.OrderByDescending(p => p.Id).Skip((_page - 1) * PageSize).Take(PageSize).ToListAsync();
    }

    private string PageUrl(int page) => Nav.GetUriWithQueryParameters(Nav.Uri.Split('?')[0], new Dictionary<string, object?>
    {
        ["searchKeyword"] = string.IsNullOrWhiteSpace(SearchKeyword) ? null : SearchKeyword,
        ["categoryId"] = CategoryId is > 0 ? CategoryId : null,
        ["storageFilter"] = string.IsNullOrWhiteSpace(StorageFilter) ? null : StorageFilter,
        ["currentPage"] = page > 1 ? page : null
    });

    private void ApplyFilter() => Nav.NavigateTo(Nav.GetUriWithQueryParameters(Nav.Uri.Split('?')[0], new Dictionary<string, object?>
    {
        ["searchKeyword"] = string.IsNullOrWhiteSpace(_keyword) ? null : _keyword.Trim(),
        ["categoryId"] = _filterCategory > 0 ? _filterCategory : null,
        ["storageFilter"] = string.IsNullOrWhiteSpace(_filterStorage) ? null : _filterStorage
    }));

    private void OpenAdd()
    {
        _edit = new Product
        {
            CategoryId = _categories.FirstOrDefault()?.Id ?? 0,
            Storage = "128GB",
            Quantity = 10,
            WarrantyMonths = 12,
            IsActive = true
        };
        _formError = null;
        _showModal = true;
    }

    private void OpenEdit(Product p)
    {
        _edit = new Product
        {
            Id = p.Id, CategoryId = p.CategoryId, Name = p.Name, ModelSeries = p.ModelSeries, Color = p.Color,
            Storage = p.Storage, Specifications = p.Specifications, Price = p.Price, Quantity = p.Quantity,
            WarrantyMonths = p.WarrantyMonths, ImageUrl = p.ImageUrl, Description = p.Description, IsActive = p.IsActive
        };
        _formError = null;
        _showModal = true;
    }

    private void CloseModal() => _showModal = false;

    private async Task SaveAsync()
    {
        if (string.IsNullOrWhiteSpace(_edit.Name) || string.IsNullOrWhiteSpace(_edit.ModelSeries) ||
            string.IsNullOrWhiteSpace(_edit.Color) || _edit.CategoryId == 0)
        {
            _formError = "Vui lòng nhập đầy đủ Tên, Model, Màu sắc và chọn Dòng máy!";
            return;
        }
        if (_edit.Price < 1_000_000 || _edit.Price > 200_000_000)
        {
            _formError = "Giá sản phẩm phải từ 1.000.000 VNĐ đến 200.000.000 VNĐ!";
            return;
        }
        if (_edit.Quantity < 0)
        {
            _formError = "Số lượng không hợp lệ!";
            return;
        }

        await using var db = await DbFactory.CreateDbContextAsync();
        if (_edit.Id == 0)
        {
            db.Products.Add(new Product
            {
                CategoryId = _edit.CategoryId, Name = _edit.Name.Trim(), ModelSeries = _edit.ModelSeries.Trim(),
                Color = _edit.Color.Trim(), Storage = _edit.Storage, Specifications = _edit.Specifications,
                Price = _edit.Price, Quantity = _edit.Quantity, WarrantyMonths = _edit.WarrantyMonths,
                ImageUrl = _edit.ImageUrl, Description = _edit.Description, IsActive = _edit.IsActive
            });
            _alert = $"Đã thêm thành công: {_edit.Name}";
        }
        else
        {
            var existing = await db.Products.FindAsync(_edit.Id);
            if (existing != null)
            {
                existing.CategoryId = _edit.CategoryId;
                existing.Name = _edit.Name.Trim();
                existing.ModelSeries = _edit.ModelSeries.Trim();
                existing.Color = _edit.Color.Trim();
                existing.Storage = _edit.Storage;
                existing.Specifications = _edit.Specifications;
                existing.Price = _edit.Price;
                existing.Quantity = _edit.Quantity;
                existing.WarrantyMonths = _edit.WarrantyMonths;
                existing.ImageUrl = _edit.ImageUrl;
                existing.Description = _edit.Description;
                existing.IsActive = _edit.IsActive;
                _alert = $"Đã cập nhật: {existing.Name}";
            }
        }
        _alertType = "success";
        await db.SaveChangesAsync();
        _showModal = false;
        await LoadAsync();
    }

    private async Task DeleteAsync(Product p)
    {
        if (!await JS.InvokeAsync<bool>("confirm", "Bạn có chắc chắn muốn xóa/ngừng kinh doanh máy này?")) return;

        await using var db = await DbFactory.CreateDbContextAsync();
        var product = await db.Products.FindAsync(p.Id);
        if (product == null) return;

        if (await db.OrderDetails.AnyAsync(od => od.ProductId == p.Id))
        {
            product.IsActive = false;
            _alert = $"iPhone {product.Name} đã có đơn hàng nên chuyển sang trạng thái ngừng kinh doanh.";
            _alertType = "warning";
        }
        else
        {
            db.Products.Remove(product);
            _alert = $"Đã xóa: {product.Name}";
            _alertType = "success";
        }
        await db.SaveChangesAsync();
        await LoadAsync();
    }

